            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                return;
            }

            const year = getCleanValue(SafeGetValue(characterData, '年分', '--'));
            const month = getCleanValue(SafeGetValue(characterData, '月份', '--'));
            const day = getCleanValue(SafeGetValue(characterData, '日期', '--'));
            document.getElementById('mio-date').innerText = `${year}/${month}/${day}`;
            updateText('mio-weekday', SafeGetValue(characterData, '星期', '...'));
            updateText('mio-time', SafeGetValue(characterData, '時間', '--:--'));
            updateText('mio-location', SafeGetValue(characterData, '地點', '未知'));

            updateText('mio-hat', SafeGetValue(characterData, '著裝.帽子', '...'));
            updateText('mio-top', SafeGetValue(characterData, '著裝.上衣', '...'));
            updateText('mio-bottom', SafeGetValue(characterData, '著裝.下衣', '...'));
            updateText('mio-bra', SafeGetValue(characterData, '著裝.內衣', '...'));
            updateText('mio-panties', SafeGetValue(characterData, '著裝.內褲', '...'));
            updateText('mio-hair-accessory', SafeGetValue(characterData, '著裝.髮飾', '...'));
            updateText('mio-necklace', SafeGetValue(characterData, '著裝.首飾', '...'));
            updateText('mio-earrings', SafeGetValue(characterData, '著裝.耳飾', '...'));
            updateText('mio-ring', SafeGetValue(characterData, '著裝.戒指', '...'));
            updateText('mio-bracelet', SafeGetValue(characterData, '著裝.手環', '...'));
            updateText('mio-gloves', SafeGetValue(characterData, '著裝.手套', '...'));
            updateText('mio-socks', SafeGetValue(characterData, '著裝.襪子', '...'));
            updateText('mio-shoes', SafeGetValue(characterData, '著裝.鞋子', '...'));
            updateText('mio-accessory', SafeGetValue(characterData, '著裝.配飾', '...'));

            updateText('mio-nipples', SafeGetValue(characterData, '祕密花園.乳頭', '...'));
            updateText('mio-pussy', SafeGetValue(characterData, '祕密花園.小穴', '...'));
            updateText('mio-anus', SafeGetValue(characterData, '祕密花園.肛門', '...'));
            updateText('mio-womb', SafeGetValue(characterData, '祕密花園.子宮', '...'));
            updateText('mio-mouth', SafeGetValue(characterData, '祕密花園.口腔', '...'));

            const pregnancyWeekRaw = SafeGetValue(characterData, '聖域.懷孕週期', '0');
            const pregnancyWeekClean = getCleanValue(pregnancyWeekRaw);
            document.getElementById('mio-pregnancy-week').innerText = (pregnancyWeekClean === '0' ? '未怀孕' : `${pregnancyWeekClean} 周`);
            updateText('mio-fetus-status', SafeGetValue(characterData, '聖域.胎兒狀況', '...'));

            updateText('mio-inner-voice', SafeGetValue(characterData, '心聲', '...'));

            updateProgressBar('mio-alert-father-bar', 'mio-alert-father', SafeGetValue(characterData, '警戒值.父親'), 1, 100, 'var(--alert-color)');
            updateProgressBar('mio-alert-mother-bar', 'mio-alert-mother', SafeGetValue(characterData, '警戒值.母親'), 1, 100, 'var(--alert-color)');

        } catch (error) {
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
